import java.util.*; public class Task03Demo {String[][] a;Task03Demo(int[]c){a=new String[c.length][];for(int i=0;i<c.length;i++)a[i]=new String[c[i]];}int[] allocate(String r){for(int f=0;f<a.length;f++)for(int s=0;s<a[f].length;s++)if(a[f][s]==null){a[f][s]=r;return new int[]{f,s};}return null;}boolean release(int f,int s){if(f<0||f>=a.length||s<0||s>=a[f].length||a[f][s]==null)return false;a[f][s]=null;return true;}static double fee(int m,double r){return ((m+59)/60)*r;}public static void main(String[]z){Task03Demo p=new Task03Demo(new int[]{2,1});System.out.println(Arrays.toString(p.allocate("TN01")));System.out.println(Arrays.toString(p.allocate("TN02")));System.out.println(Arrays.toString(p.allocate("TN03")));System.out.println(p.allocate("TN04"));System.out.println(p.release(0,1)+" "+p.release(0,1)+" "+p.release(5,0));System.out.println(Arrays.toString(p.allocate("TN04")));System.out.println("Fee 90 min at Rs30/hour: "+fee(90,30));}}